+// Access control: API keys, roles and the audit trail of changes.
+import { AppError } from "../errors.js";
+
+// What a cook may do besides reading. Managers may do everything.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+/** Finds the API key named by the Authorization header, or throws `unauthorized`. */
+export function authenticate(store, headers = {}) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(name ? String(headers[name]) : "");
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may call `method` on the route `pattern`. */
+export function authorize(key, method, pattern, path) {
+  const ok =
+    key.role === "manager" ||
+    (key.role === "cook" && (method === "GET" || COOK_ROUTES.has(`${method} ${pattern}`))) ||
+    (key.role === "viewer" && method === "GET");
+  if (!ok || (pattern === "/audit" && key.role !== "manager"))
+    throw new AppError("forbidden", { role: key.role, method, path });
+}
+
+/** Appends an audit entry for a request that may change data. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit.push({ id: store.nextId("audit"), at, key, method, path, status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
